const lessons=[{"sentences":[{"speaker":"A","text":"Hello Mark, do you have a moment to talk about your garden hedge clippers?","position":1,"audioStartSeconds":0,"audioEndSeconds":4.760166666666667},{"speaker":"B","text":"Hi Sarah, of course I do because I just finished using them yesterday.","position":2,"audioStartSeconds":4.960166666666667,"audioEndSeconds":9.694541666666666},{"speaker":"A","text":"That is wonderful news because my overgrown bushes really need some attention before the weekend arrives.","position":3,"audioStartSeconds":9.894541666666667,"audioEndSeconds":16.312833333333334},{"speaker":"B","text":"You are welcome to borrow them if you promise to clean the blades after you finish.","position":4,"audioStartSeconds":16.512833333333333,"audioEndSeconds":21.294541666666667},{"speaker":"A","text":"I will certainly clean them thoroughly and oil the joints before I bring them back.","position":5,"audioStartSeconds":21.494541666666667,"audioEndSeconds":26.430083333333332},{"speaker":"B","text":"When do you think you will actually return them to my garage?","position":6,"audioStartSeconds":26.630083333333335,"audioEndSeconds":30.483166666666666},{"speaker":"A","text":"I can bring them over on Sunday evening when I finish my gardening work.","position":7,"audioStartSeconds":30.683166666666665,"audioEndSeconds":35.1935},{"speaker":"B","text":"Sunday evening works well although I might not be home when you drop them off.","position":8,"audioStartSeconds":35.3935,"audioEndSeconds":40.084208333333336},{"speaker":"A","text":"If you are not there, I will simply leave them safely by your back door.","position":9,"audioStartSeconds":40.28420833333333,"audioEndSeconds":44.871833333333335},{"speaker":"B","text":"That plan sounds completely fine with me as long as they stay out of the rain.","position":10,"audioStartSeconds":45.07183333333333,"audioEndSeconds":49.85279166666667},{"speaker":"A","text":"Do not worry about the weather because I will place them under the porch roof.","position":11,"audioStartSeconds":50.052791666666664,"audioEndSeconds":54.56308333333333},{"speaker":"B","text":"Perfect, and let me know if you need any gardening advice while you work.","position":12,"audioStartSeconds":54.763083333333334,"audioEndSeconds":59.32491666666667},{"speaker":"A","text":"I might ask you a few questions if I encounter any difficult thick branches.","position":13,"audioStartSeconds":59.52491666666667,"audioEndSeconds":64.48629166666667},{"speaker":"B","text":"Just knock on my door whenever you need extra help with the heavy cutting.","position":14,"audioStartSeconds":64.68629166666666,"audioEndSeconds":69.06775},{"speaker":"A","text":"Thank you very much for your kindness and your helpful neighbourly support today.","position":15,"audioStartSeconds":69.26775,"audioEndSeconds":74.032625},{"speaker":"B","text":"You are very welcome and good luck with trimming your front hedge.","position":16,"audioStartSeconds":74.232625,"audioEndSeconds":78.24954166666667}],"questions":[{"prompt":"What is the main purpose of Sarah's conversation with Mark?","options":["To invite him to a weekend garden party.","To ask to borrow his garden hedge clippers.","To complain about his overgrown garden bushes."],"answer":"B","evidenceSentence":1,"evidence":"do you have a moment to talk about your garden hedge clippers","explanation":"Sarah mở đầu cuộc trò chuyện bằng cách hỏi mượn dụng cụ tỉa hàng rào của Mark."},{"prompt":"Why is Mark able to lend his clippers right now?","options":["He just finished using them yesterday.","He bought a brand new pair this morning.","He no longer cares about his garden."],"answer":"A","evidenceSentence":2,"evidence":"I just finished using them yesterday","explanation":"Mark đồng ý cho mượn ngay vì anh ấy vừa mới sử dụng xong vào ngày hôm qua."},{"prompt":"What condition does Mark set for lending his tool?","options":["Sarah must pay a small rental fee.","Sarah must buy him a new tool.","Sarah must clean the blades afterwards."],"answer":"C","evidenceSentence":4,"evidence":"if you promise to clean the blades after you finish","explanation":"Mark đặt điều kiện là Sarah phải hứa làm sạch lưỡi kéo sau khi dùng xong."},{"prompt":"When does Sarah plan to return the clippers?","options":["On Sunday evening.","On Saturday morning.","On Monday afternoon."],"answer":"A","evidenceSentence":7,"evidence":"I can bring them over on Sunday evening","explanation":"Sarah dự định sẽ mang trả dụng cụ vào tối Chủ Nhật."},{"prompt":"What will Sarah do if Mark is not home when she returns them?","options":["Take them back to her own house.","Leave them by his back door.","Hide them inside her garden shed."],"answer":"B","evidenceSentence":9,"evidence":"I will simply leave them safely by your back door","explanation":"Nếu Mark không có nhà, Sarah sẽ để chúng an toàn cạnh cửa sau của anh ấy."},{"prompt":"What does Mark tell Sarah to do if she encounters difficult branches?","options":["Call him on his mobile phone.","Knock on his door for help.","Stop gardening immediately."],"answer":"B","evidenceSentence":14,"evidence":"Just knock on my door whenever you need extra help","explanation":"Mark bảo Sarah cứ gõ cửa nhà anh ấy bất cứ lúc nào cần thêm sự trợ giúp."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
